/// 鍵盤輸入模式單一權威描述子（Mode Registry Entry）
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ModeDescriptor {
    pub id: &'static str,
    pub display_name: &'static str,
    pub short_badge: &'static str,
    pub aliases: &'static [&'static str],
}

