/// 反斜線轉義前導待命旗標（`\` 後等待 `` ` `` / `\` / `~`；具獨立 `Clone` 語意）
#[derive(Debug, Default)]
pub struct EscapePendingFlag(std::sync::atomic::AtomicBool);

impl Clone for EscapePendingFlag {
    fn clone(&self) -> Self {
        Self(std::sync::atomic::AtomicBool::new(
            self.0.load(std::sync::atomic::Ordering::Relaxed),
        ))
    }
}

#[derive(Debug, Clone, Default)]
pub struct WesternSpaceRollbackSnapshot {
    pub sentence_chars: Vec<String>,
    pub raw_ascii_buffer: String,
    pub cursor_pos: usize,
    pub corrected_len: usize,
    pub pin_range: (usize, usize),
}

#[derive(Default)]
pub struct ShiftDownRuntimeState {
    inner: std::sync::Mutex<ShiftDownRuntimeInner>,
}

#[derive(Clone, Default)]
struct ShiftDownRuntimeInner {
    last_fused_longkan: Option<(usize, Vec<String>)>,
    is_shift_down_longkan_popup: bool,
    is_shift_down_mode_picker: bool,
    active_shift_down_mode_override: Option<String>,
}

impl Clone for ShiftDownRuntimeState {
    fn clone(&self) -> Self {
        let cloned_inner = self
            .inner
            .lock()
            .map(|g| g.clone())
            .unwrap_or_default();
        Self {
            inner: std::sync::Mutex::new(cloned_inner),
        }
    }
}

