        engine.reset_buffer();
        for c in "jjhxajceldcx rxjfrfmxjvemdjxfgxl ".chars() { engine.process_key(c); }
        assert_eq!(engine.get_display_text(), "智慧型輸入法目前主攻", "必精準命中「智慧型輸入法目前主攻」，杜絕「智會行」與「主公」劫掠");

