    #[test]
    fn test_polyphone_chi_ji_blacklist_and_full_sentence_revision_capture_261021() {
        let mut engine = RuhiEngine::new();
        let _ = engine.lexicon.load_tsv("../ruhi_lexicon/data/lexicon_mcbopomofo.tsv", "mcbpmf");
        let _ = engine.lexicon.load_tsv("../ruhi_lexicon/data/lexicon_moe.tsv", "moe");
        let _ = engine.lexicon.load_tsv("../ruhi_lexicon/data/lexicon_domain.tsv", "domain");
        let _ = engine.transitions.load_tsv("../ruhi_lexicon/data/transitions_user.tsv");
        let _ = engine.transitions.load_patterns_jsonl("../ruhi_lexicon/data/patterns_user.jsonl");

        // 1. 驗證「開發者集權／極權」(`ki fy jgfjedvumd`) 絕不被「口吃」之單字破音 `吃 (ㄐㄧˊ)` 劫掠為「開發者吃全」
        engine.reset_buffer();
        for c in "ki fy jgfjedvumd".chars() {
            engine.process_key(c);
        }
        assert!(
            matches!(engine.get_display_text().as_str(), "開發者集權" | "開發者極權"),
            "開發者集權／極權絕不可遭破音『吃 (ㄐㄧˊ)』劫掠為『開發者吃全』，實際：{}",
            engine.get_display_text()
        );

        // 2. 驗證雙字複合詞「口吃」(`kofjed`) 依然正常保留
        engine.reset_buffer();
        for c in "kofjed".chars() {
            engine.process_key(c);
        }
        assert_eq!(engine.get_display_text(), "口吃");

        // 3. 驗證新詞「掠劫」(`luejjeed`) 正常輸出
        engine.reset_buffer();
        for c in "luejjeed".chars() {
            engine.process_key(c);
        }
        assert_eq!(engine.get_display_text(), "掠劫");

        // 4. 驗證手動改字後結算（標點或 Enter）會自動捕獲整句對照 (viterbi_raw_sentence ➔ composed_sentence) 且不竄改記憶體轉移矩陣
        engine.reset_buffer();
        let trans_count_before = engine.transitions.transitions.len();
        for c in "xhfds".chars() {
            engine.process_key(c);
        }
        assert_eq!(engine.viterbi_raw_sentence, "我的");
        assert_eq!(engine.composed_sentence, "我的");

        // 模擬使用者按 Q 將「的」改為下一個同音候選字
        engine.cycle_next_candidate();
        assert_eq!(engine.viterbi_raw_sentence, "我的");
        assert_ne!(engine.composed_sentence, "我的");
        assert!(!engine.pending_revisions.is_empty());

        // 測試 capture_sentence_revision_before_commit 補齊整句錯誤句與正確句
        let expected_cor = format!("{}。", engine.composed_sentence);
        let full_err = format!("{}。", engine.viterbi_raw_sentence);
        for rev in &mut engine.pending_revisions {
            rev.error_sentence = full_err.clone();
            rev.correct_sentence = expected_cor.clone();
        }
        assert_eq!(engine.pending_revisions[0].error_sentence, "我的。");
        assert_eq!(engine.pending_revisions[0].correct_sentence, expected_cor);
        assert_eq!(
            engine.transitions.transitions.len(),
            trans_count_before,
            "Capturing full-sentence revision must never pollute local transitions matrix"
        );
    }

    #[test]
    fn test_korean_rr_mode_integration() {
        let mut engine = RuhiEngine::default();

        // 0. 確認預設 enabled_keyboard_modes 未被加入 korean
        assert_eq!(
            engine.enabled_keyboard_modes,
            vec!["hsu".to_string(), "japanese".to_string()]
        );

        // 1. set_keyboard_mode("ko") 正規化為 "korean"，徽章為 "韓"
        engine.set_keyboard_mode("ko");
        assert_eq!(engine.keyboard_mode, "korean");
        assert_eq!(engine.get_keyboard_mode_badge(), "韓");
        assert_eq!(engine.last_keyboard_mode, "hsu");

        // 行列教練於韓文模式下必須為空
        engine.enable_array30_coach = true;
        assert_eq!(engine.get_array30_coach_hint(), "");

        // 2. 在 korean 模式下鍵入 "hangeul" 再按 Space，committed_chunk == "한글 "
        for ch in "hangeul".chars() {
            let r = engine.process_key(ch);
            assert_eq!(r.action, "compose");
        }
        assert_eq!(engine.composed_sentence, "한글");
        let r_space = engine.process_key_str("Space");
        assert_eq!(r_space.action, "commit");
        assert_eq!(r_space.committed_chunk, "한글 ");
        assert!(engine.composed_sentence.is_empty());

        // 3. Down 與數字選字路由至韓文分支
        for ch in "hangeul".chars() {
            engine.process_key(ch);
        }
        let r_down = engine.process_key_str("Down");
        assert_eq!(r_down.action, "show_candidate_popup");
        assert_eq!(r_down.mode, "candidates");
        assert!(r_down.candidates.len() >= 2);
        assert_eq!(r_down.candidates[0], "한글");
        assert!(r_down.candidates.contains(&"항을".to_string()));
        assert_eq!(engine.mode, EngineMode::CandidatePopup);

        // 測試數字選字 (按 '2' 立即結算第 2 個候選)
        let second_cand = r_down.candidates[1].clone();
        let r_digit = engine.process_key('2');
        assert_eq!(r_digit.action, "commit");
        assert_eq!(r_digit.committed_chunk, second_cand);
        assert!(engine.composed_sentence.is_empty());
        assert_eq!(engine.mode, EngineMode::Normal);

        // 4. Up (學習者骨架救援) 與 select_candidate 路由至韓文分支
        for ch in "kimchi".chars() {
            engine.process_key(ch);
        }
        assert_eq!(engine.composed_sentence, "킴치");
        let r_up = engine.process_key_str("Up");
        assert_eq!(r_up.action, "show_candidate_popup");
        assert_eq!(r_up.mode, "candidates");
        assert_eq!(r_up.candidates.first().map(|s| s.as_str()), Some("김치"));
        assert_eq!(engine.composed_sentence, "김치");
        assert_eq!(engine.select_candidate(0), Some("김치".to_string()));

        // 5. 從 korean 切回 hsu 時緩衝區清空，last_keyboard_mode == "korean"
        engine.set_keyboard_mode("hsu");
        assert_eq!(engine.keyboard_mode, "hsu");
        assert_eq!(engine.last_keyboard_mode, "korean");
        assert_eq!(engine.get_keyboard_mode_badge(), "許");
        assert!(engine.composed_sentence.is_empty());
        assert!(engine.korean.raw_romaja.is_empty());
        assert!(engine.korean.candidates.is_empty());
    }

    #[test]
    fn test_gan_en_na_jiu_shui_liang_jiao_hou_lai_chu_li() {
        let mut engine = RuhiEngine::new_with_data_dir("../ruhi_lexicon/data");

        // 正向驗證：離合動詞「睡 × 動量/時量中綴 × 覺」與時間連謂「後來處理」構式
        let cases = [
            ("cxajlekfjewjhojlidvxflef", "睡兩覺後來處理"),
            ("nyjjeojcxajlekfjewjhojlidvxflef", "那就睡兩覺後來處理"),
            ("gmfn ,nyjjeojcxajlekfjewjhojlidvxflef", "感恩，那就睡兩覺後來處理"),
            ("gmfn nyjjeojcxajlekfjewjhojlidvxflef", "感恩那就睡兩覺後來處理"),
            ("cxaje jewj", "睡一覺"),
            ("cxajejjewj", "睡一覺"),
            ("cxajggshwfjewj", "睡個好覺"),
            ("cxajggjhwfjewj", "睡個好覺"),
            ("maflafje xftewdjeojgl cen cunjlemjedaj", "每累積五條就更新訓練一次"),
            ("xajmemfzijajxkjjej", "為免再次忘記"),
        ];

        for (keys, expected) in &cases {
            engine.reset_buffer();
            let mut out = String::new();
            for c in keys.chars() {
                let r = engine.process_key(c);
                if !r.committed_chunk.is_empty() {
                    out.push_str(&r.committed_chunk);
                }
            }
            out.push_str(&engine.get_display_text());
            assert_eq!(out, *expected, "輸入按鍵 {} 應精確解碼為 {}", keys, expected);
        }

        // 對抗反例保護驗證：確保「繳稅 / 報稅」、「教兩位學生」、「叫兩個人來處理」零副作用
        let counter_cases = [
            ("jewfcxaj", "繳稅"),
            ("bwjcxaj", "報稅"),
            ("jewjlekfxajcuedcl ", "教兩位學生"),
            ("jewjlekfggsrndlidvxflef", "叫兩個人來處理"),
            ("maflejdsfl jelf", "美麗的風景"),
            ("jgjxajmemftijkxy jk lgs", "這未免太誇張了"),
        ];
        for (keys, expected) in &counter_cases {
            engine.reset_buffer();
            let mut out = String::new();
            for c in keys.chars() {
                let r = engine.process_key(c);
                if !r.committed_chunk.is_empty() {
                    out.push_str(&r.committed_chunk);
                }
            }
            out.push_str(&engine.get_display_text());
            assert_eq!(out, *expected, "對抗反例按鍵 {} 應保持 {}", keys, expected);
        }
    }

    #[test]
    fn test_four_corner_mode_integration() {
        let mut engine = RuhiEngine::new_with_data_dir("../ruhi_lexicon/data");
        engine.set_keyboard_mode("4corner");
        assert_eq!(engine.keyboard_mode, "four_corner");
        assert_eq!(engine.get_keyboard_mode_badge(), "四");

        // 1. 雙字詞前兩角簡碼（帶 `-` 詞前導）：-2332 -> 台灣, -1072 -> 電腦
        let mut committed = String::new();
        for ch in "-2332+-1072+".chars() {
            let r = engine.process_key(ch);
            if !r.committed_chunk.is_empty() {
                committed.push_str(&r.committed_chunk);
            }
        }
        assert_eq!(committed, "台灣電腦");

        // 2. 驗證正異體雙向共享：-4032 亦能命中「臺灣」與「台灣」
        for ch in "-4032".chars() {
            engine.process_key(ch);
        }
        assert!(engine.current_candidates.contains(&"臺灣".to_string()));
        assert!(engine.current_candidates.contains(&"台灣".to_string()));
        engine.reset_buffer();

        // 3. 驗證 `.` 小鍵盤標點符號選單前導與 `..` 快速逗號
        engine.process_key('.');
        let r_comma = engine.process_key('.');
        assert_eq!(r_comma.action, "commit_punctuation");
        assert_eq!(r_comma.committed_chunk, "，");

        // 4. 驗證三字詞 5 碼 (-50843 -> 輸入法) 與四字詞 6 碼 (-622612 -> 四角號碼) 及 `+` vs `Enter` 分流
        let mut phrase_out = String::new();
        for ch in "-50843+".chars() {
            let r = engine.process_key(ch);
            if !r.committed_chunk.is_empty() {
                assert_eq!(r.action, "commit");
                phrase_out.push_str(&r.committed_chunk);
            }
        }
        for ch in "-622612\n".chars() {
            let r = engine.process_key(ch);
            if !r.committed_chunk.is_empty() {
                assert_eq!(r.action, "commit_enter");
                phrase_out.push_str(&r.committed_chunk);
            }
        }
        assert_eq!(phrase_out, "輸入法四角號碼");
    }

    #[test]
    fn test_universal_cross_ime_reverse_lookup_v070() {
        let mut engine = RuhiEngine::new();
        engine.set_keyboard_mode("hsu");

        // 1. 一次反查全系統 7 種輸入法方案（龍龕形音、四角、行列30、倉頡、許氏、標準大千、倚天26鍵）
        let breakdowns = engine.inspect_text_across_all_methods("台灣");
        assert_eq!(breakdowns.len(), 7);
        assert!(breakdowns.iter().any(|b| b.method_id == "longkan" && b.coach_line.contains("龍龕教練")));
        assert!(breakdowns.iter().any(|b| b.method_id == "four_corner" && b.coach_line.contains("-2332")));
        assert!(breakdowns.iter().any(|b| b.method_id == "array30" && b.coach_line.contains("行列教練")));
        assert!(breakdowns.iter().any(|b| b.method_id == "cangjie" && b.coach_line.contains("倉頡教練")));
        assert!(breakdowns.iter().any(|b| b.method_id == "hsu" && b.coach_line.contains("TID")));
        assert!(breakdowns.iter().any(|b| b.method_id == "standard" && b.coach_line.contains("W96")));
        assert!(breakdowns.iter().any(|b| b.method_id == "et26" && b.coach_line.contains("TIF")));

        // 2. 在許氏注音下打「台灣」，切換不同 reverse_coach_target 皆能動態反查對應編碼
        for c in "tidxm ".chars() {
            engine.process_key(c);
        }
        assert_eq!(engine.composed_sentence, "台灣");

        engine.reverse_coach_target = "longkan".to_string();
        let lk_hint = engine.get_universal_coach_hint();
        assert!(lk_hint.contains("🎯 龍龕教練") && lk_hint.contains("KOTI"), "實際：{}", lk_hint);

        engine.reverse_coach_target = "four_corner".to_string();
        let fc_hint = engine.get_universal_coach_hint();
        assert!(fc_hint.contains("🎯 四角教練") && fc_hint.contains("-2332"), "實際：{}", fc_hint);

        engine.reverse_coach_target = "cangjie".to_string();
        let cj_hint = engine.get_universal_coach_hint();
        assert!(cj_hint.contains("🎯 倉頡教練") && cj_hint.contains("IR"), "實際：{}", cj_hint);

        engine.reverse_coach_target = "standard".to_string();
        let std_hint = engine.get_universal_coach_hint();
        assert!(std_hint.contains("🎯 大千教練") && std_hint.contains("W96"), "實際：{}", std_hint);

        // 3. 在四角號碼模式下打「2360」預覽「台」，反查許氏雙拼與行列 30
        engine.set_keyboard_mode("four_corner");
        for c in "2360".chars() {
            engine.process_key(c);
        }
        engine.reverse_coach_target = "hsu".to_string();
        let fc_to_hsu = engine.get_universal_coach_hint();
        assert!(fc_to_hsu.contains("🎯 許氏教練") && fc_to_hsu.contains("TID"), "實際：{}", fc_to_hsu);
    }

